CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_test_prepare(p_job uuid, p_fence uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.tenant_smtp_test_receipts; s public.communication_tenant_email_settings; v_org uuid; v_password text; v_email text;
BEGIN
 SELECT organization_id INTO v_org FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job;
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job FOR UPDATE;
 IF r.actor_id IS DISTINCT FROM p_actor OR r.fence IS DISTINCT FROM p_fence OR r.state<>'claimed'
 OR platform_private.tenant_smtp_test_actor(p_actor) IS DISTINCT FROM v_org THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 -- Service JWT cannot substitute actor iat. Preserve claim's actual invitation fence.
 IF r.actor_iat<=0 OR EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_actor
 AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND to_timestamp(r.actor_iat)<=i.access_valid_after))) THEN
 RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR UPDATE;
 IF s.version IS DISTINCT FROM r.version THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE approved AND id) OR s.config->>'port'<>'465'
 OR s.config->>'tls_mode'<>'implicit_tls' OR r.created_at<clock_timestamp()-interval '30 seconds' THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 IF r.mode='send' AND NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_receipts WHERE organization_id=v_org AND actor_id=p_actor
 AND mode='connection' AND version=r.version AND code='smtp_connection_ok' AND completed_at>clock_timestamp()-interval '5 minutes') THEN RAISE EXCEPTION 'SMTP_NOT_READY' USING ERRCODE='42501'; END IF;
 SELECT email INTO v_email FROM auth.users WHERE id=p_actor AND email_confirmed_at IS NOT NULL;
 SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=v_org;
 IF v_password IS NULL OR v_email IS NULL THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 UPDATE platform_private.tenant_smtp_test_receipts SET state='executing' WHERE id=p_job;
 RETURN jsonb_build_object('mode',r.mode,'version',r.version,'recipient',v_email,'config',s.config,'password',v_password);
EXCEPTION WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_test_finish(p_job uuid, p_fence uuid, p_actor uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r platform_private.tenant_smtp_test_receipts; v_org uuid;
BEGIN
 SELECT organization_id INTO v_org FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job;
 IF v_org IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(v_org::text,0));
 SELECT * INTO r FROM platform_private.tenant_smtp_test_receipts WHERE id=p_job FOR UPDATE;
 IF r.actor_id IS DISTINCT FROM p_actor OR r.fence IS DISTINCT FROM p_fence OR r.state NOT IN ('executing','complete')
 THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_code IS NULL OR p_code NOT IN ('smtp_connection_ok','smtp_send_accepted','smtp_send_ambiguous','smtp_test_failed')
 OR (r.mode='connection' AND p_code IN ('smtp_send_accepted','smtp_send_ambiguous')) OR (r.mode='send' AND p_code='smtp_connection_ok') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 IF r.state='complete' AND r.code<>p_code THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF r.state<>'complete' THEN
 UPDATE platform_private.tenant_smtp_test_receipts SET state='complete',code=p_code,completed_at=clock_timestamp() WHERE id=p_job;
 UPDATE public.comunicacao_outbox SET status=CASE WHEN p_code='smtp_send_accepted' THEN 'sent'::public.comunicacao_outbox_status ELSE 'dead_letter'::public.comunicacao_outbox_status END,
 error_code=p_code,error_message=NULL,lease_expires_at=NULL,locked_by=NULL WHERE id=r.outbox_id;
 INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(v_org,p_actor,r.version,p_code);
 END IF;
 -- Record results even if actor revoked after socket; never return result to revoked actor.
 RETURN jsonb_build_object('code',p_code,'version',r.version,'mode',r.mode,'dispatch_enabled',false,'sender_verified',false);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_sender_challenge_prepare(p_challenge uuid, p_fence uuid, p_actor uuid, p_salt text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.tenant_smtp_sender_challenges; s public.communication_tenant_email_settings; v_password text;
BEGIN
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge;
 IF c.id IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c.organization_id::text,0));
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge FOR UPDATE;
 IF c.actor_id IS DISTINCT FROM p_actor OR c.fence IS DISTINCT FROM p_fence OR c.state<>'claimed'
 OR platform_private.tenant_smtp_test_actor(p_actor) IS DISTINCT FROM c.organization_id THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF c.actor_iat<=0 OR EXISTS(SELECT 1 FROM public.platform_org_admin_invites i WHERE i.user_id=p_actor
  AND (i.access_operation_status='processing' OR (i.access_valid_after IS NOT NULL AND to_timestamp(c.actor_iat)<=i.access_valid_after))) THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_salt IS NULL OR p_salt !~ '^[0-9a-f]{32}$' OR p_hash IS NULL OR p_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=c.organization_id FOR UPDATE;
 IF s.version IS DISTINCT FROM c.version OR lower(s.config->>'from_email') IS DISTINCT FROM c.from_email THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_f4_gate WHERE id AND approved) OR NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_test_gate WHERE id AND approved)
 OR s.config->>'port'<>'465' OR s.config->>'tls_mode'<>'implicit_tls' OR c.created_at<clock_timestamp()-interval '30 seconds' THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=c.organization_id;
 IF v_password IS NULL THEN RAISE EXCEPTION 'SMTP_UNAVAILABLE' USING ERRCODE='42501'; END IF;
 UPDATE platform_private.tenant_smtp_sender_challenges SET state='executing',code_salt=p_salt,code_hash=p_hash,expires_at=clock_timestamp()+interval '15 minutes' WHERE id=p_challenge;
 RETURN jsonb_build_object('version',c.version,'recipient',c.from_email,'config',s.config,'password',v_password);
EXCEPTION WHEN SQLSTATE '42501' THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501';
 WHEN SQLSTATE '40001' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_sender_challenge_finish(p_challenge uuid, p_fence uuid, p_actor uuid, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c platform_private.tenant_smtp_sender_challenges; v_state text;
BEGIN
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge;
 IF c.id IS NULL THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(c.organization_id::text,0));
 SELECT * INTO c FROM platform_private.tenant_smtp_sender_challenges WHERE id=p_challenge FOR UPDATE;
 IF c.actor_id IS DISTINCT FROM p_actor OR c.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_code IS NULL OR p_code NOT IN ('challenge_sent','challenge_ambiguous','challenge_failed') THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 v_state:=CASE p_code WHEN 'challenge_sent' THEN 'sent' WHEN 'challenge_ambiguous' THEN 'ambiguous' ELSE 'failed' END;
 IF c.state='executing' THEN
  -- Failed: discard hash; ambiguous: keep confirmable (code arrival proves possession), never auto-resend.
  UPDATE platform_private.tenant_smtp_sender_challenges SET state=v_state,
   code_hash=CASE WHEN v_state='failed' THEN NULL ELSE code_hash END, code_salt=CASE WHEN v_state='failed' THEN NULL ELSE code_salt END,
   closed_at=CASE WHEN v_state='failed' THEN clock_timestamp() END WHERE id=p_challenge;
  INSERT INTO public.communication_tenant_email_audit(organization_id,actor_id,version,action) VALUES(c.organization_id,p_actor,c.version,'sender_'||p_code);
 ELSIF c.state IS DISTINCT FROM v_state AND c.state NOT IN ('invalidated','verified','exhausted','expired') THEN
  RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 END IF;
 RETURN jsonb_build_object('code',p_code,'version',c.version,'dispatch_enabled',false);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_claim(p_worker text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs; s public.communication_tenant_email_settings; v_email text; v_password text; v_fence uuid;
 o public.comunicacao_outbox; v_num text; v_body text; v_reason text; v_org uuid;
BEGIN
 IF p_worker IS NULL OR p_worker !~ '^[A-Za-z0-9._-]{1,80}$' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE state IN ('executing','authorized') AND lease_expires_at<clock_timestamp() FOR UPDATE SKIP LOCKED LOOP
  IF j.state='executing' THEN
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='failed',result_code='lease_expired_before_auth',finished_at=clock_timestamp() WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET status='failed',error_code='tenant_smtp_lease_expired_before_auth',locked_by=NULL WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'reconciled','lease_expired_before_auth',NULL);
  ELSE
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='lease_expired',result_code='lease_expired_after_auth',finished_at=clock_timestamp() WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET status='dead_letter',error_code='tenant_smtp_lease_expired',locked_by=NULL WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'reconciled','lease_expired_after_auth',NULL);
  END IF;
 END LOOP;
 FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE state='queued' AND created_at<clock_timestamp()-interval '24 hours' FOR UPDATE SKIP LOCKED LOOP
  PERFORM platform_private.tenant_smtp_lane_cancel(j,'stale_queue',NULL);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM platform_private.tenant_smtp_dispatch_gate WHERE id AND approved) THEN RETURN NULL; END IF;
 INSERT INTO platform_private.tenant_smtp_lane_heartbeat VALUES(true,p_worker,clock_timestamp()) ON CONFLICT(id) DO UPDATE SET worker=EXCLUDED.worker,seen_at=EXCLUDED.seen_at;
 FOR v_org IN SELECT q.organization_id FROM platform_private.tenant_smtp_dispatch_jobs q WHERE q.state='queued'
  GROUP BY q.organization_id ORDER BY min(q.created_at) LIMIT 25 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(v_org::text,0)) THEN CONTINUE; END IF;
  SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=v_org FOR SHARE;
  IF NOT tenant_smtp_executor.tenant_smtp_dispatch_ready(v_org) THEN
   PERFORM platform_private.tenant_smtp_lane_cancel_queued(v_org,'tenant_not_ready',NULL); CONTINUE;
  END IF;
  IF (SELECT count(*) FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org
   AND state IN ('executing','authorized','sent','ambiguous','lease_expired') AND started_at>clock_timestamp()-interval '1 hour')>=20 THEN CONTINUE; END IF;
  SELECT d.decrypted_secret INTO v_password FROM platform_private.communication_tenant_email_secret_refs t JOIN vault.decrypted_secrets d ON d.id=t.secret_id WHERE t.organization_id=v_org;
  IF v_password IS NULL THEN CONTINUE; END IF;
  FOR j IN SELECT * FROM platform_private.tenant_smtp_dispatch_jobs WHERE organization_id=v_org AND state='queued' ORDER BY created_at LIMIT 5 FOR UPDATE SKIP LOCKED LOOP
   IF s.version IS DISTINCT FROM j.version THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,'tenant_not_ready',NULL); CONTINUE; END IF;
   v_reason:=platform_private.tenant_smtp_lane_source_reason(j.source_id,j.cliente_id,j.organization_id,j.recipient_user_id);
   IF v_reason IS NOT NULL THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,v_reason,NULL); CONTINUE; END IF;
   SELECT * INTO o FROM public.comunicacao_outbox WHERE id=j.outbox_id FOR UPDATE;
   IF o.recipient_user_id IS DISTINCT FROM j.recipient_user_id OR o.status<>'processing' OR o.template_chave<>j.contract OR o.attempts<>0 THEN
    PERFORM platform_private.tenant_smtp_lane_cancel(j,'outbox_mismatch',NULL); CONTINUE;
   END IF;
   v_email:=platform_private.tenant_smtp_lane_recipient(j.organization_id,j.recipient_user_id);
   IF v_email IS NULL THEN PERFORM platform_private.tenant_smtp_lane_cancel(j,'recipient_unproven',NULL); CONTINUE; END IF;
   v_fence:=gen_random_uuid();
   UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='executing',fence=v_fence,worker=p_worker,lease_expires_at=clock_timestamp()+interval '45 seconds',started_at=clock_timestamp(),
    recipient_hash=platform_private.tenant_smtp_lane_recipient_hash(j.outbox_id,v_email) WHERE outbox_id=j.outbox_id;
   UPDATE public.comunicacao_outbox SET attempts=1,locked_at=clock_timestamp() WHERE id=j.outbox_id;
   PERFORM platform_private.tenant_smtp_lane_log(j,'claimed',NULL,NULL);
   v_num:=coalesce(o.payload_snapshot->>'numero','');
   v_body:='Uma solicitação técnica foi atribuída a você'||CASE WHEN v_num<>'' THEN ' (nº '||v_num||')' ELSE '' END||'.'||chr(10)||
    'Tipo: '||coalesce(o.payload_snapshot->>'tipo_demanda','-')||chr(10)||'Urgência: '||coalesce(o.payload_snapshot->>'urgencia','-')||chr(10)||
    'Acesse o painel Cultivo Farm para ver os detalhes. Esta mensagem é automática.';
   RETURN jsonb_build_object('outbox_id',j.outbox_id,'fence',v_fence,'version',j.version,'recipient',v_email,
    'subject',left('Nova solicitação atribuída'||CASE WHEN v_num<>'' THEN ' — nº '||v_num ELSE '' END,200),'text',v_body,
    'config',s.config,'password',v_password);
  END LOOP;
 END LOOP;
 RETURN NULL;
EXCEPTION WHEN SQLSTATE '22023' THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023';
 WHEN OTHERS THEN RAISE EXCEPTION 'SMTP_INTERNAL';
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_authorize(p_outbox uuid, p_fence uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs; s public.communication_tenant_email_settings; v_reason text; v_email text;
BEGIN
 IF p_outbox IS NULL OR p_fence IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO j FROM platform_private.tenant_smtp_dispatch_jobs WHERE outbox_id=p_outbox FOR UPDATE;
 IF NOT FOUND OR j.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF j.state<>'executing' OR j.lease_expires_at IS NULL OR j.lease_expires_at<=clock_timestamp() THEN
  RETURN jsonb_build_object('ok',false,'reason','lease_lost');
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(j.organization_id::text,0));
 SELECT * INTO s FROM public.communication_tenant_email_settings WHERE organization_id=j.organization_id FOR SHARE;
 IF NOT tenant_smtp_executor.tenant_smtp_dispatch_ready(j.organization_id) OR s.version IS DISTINCT FROM j.version THEN v_reason:='tenant_not_ready';
 ELSE v_reason:=platform_private.tenant_smtp_lane_source_reason(j.source_id,j.cliente_id,j.organization_id,j.recipient_user_id); END IF;
 IF v_reason IS NULL THEN
  v_email:=platform_private.tenant_smtp_lane_recipient(j.organization_id,j.recipient_user_id);
  IF v_email IS NULL OR j.recipient_hash IS NULL OR platform_private.tenant_smtp_lane_recipient_hash(j.outbox_id,v_email)<>j.recipient_hash THEN v_reason:='recipient_changed'; END IF;
 END IF;
 IF v_reason IS NOT NULL THEN
  PERFORM platform_private.tenant_smtp_lane_cancel(j,v_reason,NULL);
  PERFORM platform_private.tenant_smtp_lane_log(j,'withheld',v_reason,NULL);
  RETURN jsonb_build_object('ok',false,'reason',v_reason);
 END IF;
 UPDATE platform_private.tenant_smtp_dispatch_jobs SET state='authorized',authorized_at=clock_timestamp(),lease_expires_at=clock_timestamp()+interval '30 seconds' WHERE outbox_id=p_outbox;
 PERFORM platform_private.tenant_smtp_lane_log(j,'authorized',NULL,NULL);
 RETURN jsonb_build_object('ok',true);
END $function$

CREATE OR REPLACE FUNCTION tenant_smtp_executor.tenant_smtp_lane_finish(p_outbox uuid, p_fence uuid, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE j platform_private.tenant_smtp_dispatch_jobs;
BEGIN
 IF p_outcome IS NULL OR p_outcome NOT IN ('sent','failed','ambiguous') OR p_outbox IS NULL OR p_fence IS NULL THEN RAISE EXCEPTION 'SMTP_INVALID' USING ERRCODE='22023'; END IF;
 SELECT * INTO j FROM platform_private.tenant_smtp_dispatch_jobs WHERE outbox_id=p_outbox FOR UPDATE;
 IF NOT FOUND OR j.fence IS DISTINCT FROM p_fence THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 IF j.state='lease_expired' THEN
  PERFORM platform_private.tenant_smtp_lane_log(j,'late_finish','late_'||p_outcome,NULL);
  RETURN jsonb_build_object('state','lease_expired','replay',true,'lost',true);
 END IF;
 IF j.state IN ('sent','failed','ambiguous','cancelled') THEN
  IF j.state=p_outcome THEN RETURN jsonb_build_object('state',j.state,'replay',true,'lost',false); END IF;
  RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001';
 END IF;
 IF j.state='executing' AND p_outcome<>'failed' THEN RAISE EXCEPTION 'SMTP_CONFLICT' USING ERRCODE='40001'; END IF;
 UPDATE platform_private.tenant_smtp_dispatch_jobs SET state=p_outcome,result_code='smtp_'||p_outcome,finished_at=clock_timestamp(),lease_expires_at=NULL WHERE outbox_id=p_outbox;
 UPDATE public.comunicacao_outbox SET status=(CASE p_outcome WHEN 'sent' THEN 'sent' WHEN 'failed' THEN 'failed' ELSE 'dead_letter' END)::public.comunicacao_outbox_status,
  sent_at=CASE WHEN p_outcome='sent' THEN clock_timestamp() END,error_code=CASE WHEN p_outcome='sent' THEN NULL ELSE 'tenant_smtp_'||p_outcome END,locked_by=NULL
  WHERE id=p_outbox;
 PERFORM platform_private.tenant_smtp_lane_log(j,p_outcome,NULL,NULL);
 RETURN jsonb_build_object('state',p_outcome,'replay',false,'lost',false);
END $function$

CREATE OR REPLACE FUNCTION finance_private.set_payable_allocations(p_payable_id uuid, p_allocations jsonb, p_reason text, p_expected_version integer, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE u uuid:=auth.uid(); a public.accounts_payable%ROWTYPE; current_version integer; line jsonb; cc uuid; amt numeric; sm numeric:=0; seen uuid[]:='{}'; normalized jsonb:='[]'; enriched jsonb:='[]'; nm text; cd text; fp text; prior public.payable_allocation_versions%ROWTYPE; result_id uuid;
BEGIN
 IF u IS NULL OR public.is_financial_staff(u) IS NOT TRUE THEN RAISE EXCEPTION 'FIN_ALLOCATION_FORBIDDEN' USING ERRCODE='42501'; END IF;
 IF p_request_key IS NULL OR p_expected_version IS NULL OR p_expected_version<0 THEN RAISE EXCEPTION 'FIN_ALLOCATION_REQUEST' USING ERRCODE='23514'; END IF;
 IF p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'FIN_ALLOCATION_REASON' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(p_allocations) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
 IF jsonb_array_length(p_allocations) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(p_allocations) LOOP
  IF jsonb_typeof(line) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'FIN_ALLOCATION_ITEMS' USING ERRCODE='23514'; END IF;
  BEGIN cc:=(line->>'cost_center_id')::uuid; amt:=(line->>'amount')::numeric;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FIN_ALLOCATION_VALUE' USING ERRCODE='23514'; END;
  IF cc IS NULL OR cc=ANY(seen) OR amt IS NULL OR amt::text IN('NaN','Infinity','-Infinity') OR amt<=0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'FIN_ALLOCATION_VALUE' USING ERRCODE='23514'; END IF;
  seen:=array_append(seen,cc);sm:=sm+amt;
  normalized:=normalized||jsonb_build_array(jsonb_build_object('cost_center_id',cc,'amount',round(amt,2)));
 END LOOP;
 SELECT jsonb_agg(x ORDER BY x->>'cost_center_id') INTO normalized FROM jsonb_array_elements(normalized) x;
 fp:=md5(jsonb_build_object('items',normalized,'reason',btrim(p_reason),'expected_version',p_expected_version)::text);
 SELECT * INTO a FROM public.accounts_payable WHERE id=p_payable_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FIN_ALLOCATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
 SELECT * INTO prior FROM public.payable_allocation_versions WHERE payable_id=p_payable_id AND request_key=p_request_key;
 IF FOUND THEN
  IF prior.request_fingerprint<>fp THEN RAISE EXCEPTION 'FIN_ALLOCATION_IDEMPOTENCY_CONFLICT' USING ERRCODE='23514'; END IF;
  RETURN jsonb_build_object('success',true,'id',prior.id,'version',prior.version,'replayed',true);
 END IF;
 IF a.status='CANCELED' THEN RAISE EXCEPTION 'FIN_ALLOCATION_CANCELED' USING ERRCODE='23514'; END IF;
 SELECT coalesce(max(version),0) INTO current_version FROM public.payable_allocation_versions WHERE payable_id=p_payable_id;
 IF current_version<>p_expected_version THEN RAISE EXCEPTION 'FIN_ALLOCATION_STALE' USING ERRCODE='23514'; END IF;
 IF sm<>a.total_amount THEN RAISE EXCEPTION 'FIN_ALLOCATION_SUM' USING ERRCODE='23514'; END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(normalized) LOOP
  cc:=(line->>'cost_center_id')::uuid;
  SELECT name,code INTO nm,cd FROM public.financial_cost_centers WHERE id=cc AND active FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'FIN_ALLOCATION_CENTER_INACTIVE' USING ERRCODE='23514'; END IF;
  enriched:=enriched||jsonb_build_array(line||jsonb_build_object('cost_center_name',nm,'cost_center_code',cd));
 END LOOP;
 INSERT INTO public.payable_allocation_versions(payable_id,version,total_amount,allocations,reason,request_key,request_fingerprint,created_by)
 VALUES(p_payable_id,current_version+1,a.total_amount,enriched,btrim(p_reason),p_request_key,fp,u) RETURNING id INTO result_id;
 UPDATE public.accounts_payable SET cost_center_id=CASE WHEN jsonb_array_length(enriched)=1 THEN (enriched->0->>'cost_center_id')::uuid ELSE NULL END WHERE id=p_payable_id;
 INSERT INTO public.financial_audit_log(entity_type,entity_id,action,old_data,new_data,performed_by,reason)
 VALUES('accounts_payable',p_payable_id,'COST_ALLOCATION_VERSION_CREATED',jsonb_build_object('version',current_version,'cost_center_id',a.cost_center_id),jsonb_build_object('allocation_id',result_id,'version',current_version+1,'reason',btrim(p_reason),'allocations',enriched),u,btrim(p_reason));
 RETURN jsonb_build_object('success',true,'id',result_id,'version',current_version+1,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION finance_private.protect_allocated_payable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v public.payable_allocation_versions%ROWTYPE; expected_center uuid;
BEGIN
 SELECT * INTO v FROM public.payable_allocation_versions WHERE payable_id=NEW.id ORDER BY version DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NEW; END IF;
 IF NEW.total_amount IS DISTINCT FROM v.total_amount THEN RAISE EXCEPTION 'FIN_ALLOCATION_TOTAL_LOCKED' USING ERRCODE='23514'; END IF;
 expected_center:=CASE WHEN jsonb_array_length(v.allocations)=1 THEN (v.allocations->0->>'cost_center_id')::uuid ELSE NULL END;
 IF NEW.cost_center_id IS DISTINCT FROM expected_center THEN RAISE EXCEPTION 'FIN_ALLOCATION_USE_RPC' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$
